contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount <= address(c).balance, "withdrawal exceeds contract balance");

        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        uint beforeDepositsCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Withdrawal is expected to succeed (amount not exceeding balance), so no try/catch is used.
        c.withdraw(amount); if (__ESBMC_reverted()) return;

        assert(address(c).balance == beforeContractBalance - amount &&
               address(this).balance == beforeThisBalance + amount &&
               c.depositsCount() == beforeDepositsCount);
    }

    receive() external payable {}
}

