// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount <= address(c).balance);
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        uint256 beforeDepositsCount;
        try c.depositsCount() returns (uint256 __r) { beforeDepositsCount = __r; } catch { return; }
        try c.withdraw(amount) {} catch { return; }
        assertTrue(address(c).balance == beforeContractBalance - amount &&
               address(this).balance == beforeThisBalance + amount &&
               c.depositsCount() == beforeDepositsCount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
